            EvalEnv.ReportFolder);
        Directory.CreateDirectory(outDir);
        var html = Path.Combine(outDir, "report.html");

        var psi = new ProcessStartInfo("dotnet",
            $"tool run aieval report --path \"{ReportingConfig.StorageRoot}\" --output \"{html}\"")
        {
